import json
from pathlib import Path
p=Path('public/content/game.json');c=json.loads(p.read_text())
def q(id,question,kind,options,correct,feedback,revision,matches=[]):return dict(id=id,question=question,kind=kind,options=options,correct=correct,feedback=feedback,revision=revision,matches=matches)
c['finalAssessment']=[dict(id='A',title='Sebab pengenalan Rukun Negara',objective=c['learningObjectives'][0],questions=[q('akhir-sebab','Pilih tiga sebab pengenalan Rukun Negara.','multi',['Perbezaan kegiatan ekonomi','Peristiwa 13 Mei 1969','Pengasingan tempat tinggal','Perbezaan fahaman politik'],[0,2,3],'Tiga sebab ialah ekonomi, pengasingan tempat tinggal dan fahaman politik. Peristiwa 13 Mei ialah latar sejarah.','Bezakan latar peristiwa dengan tiga sebab. Lihat semula Misi 1.'),q('akhir-hubungan','Susun hubungan sebab dan keperluan ini.','order',['Hubungan antara masyarakat menjadi renggang','Perpaduan perlu diperkukuh melalui Rukun Negara','Masyarakat kurang berinteraksi kerana pengasingan tempat tinggal'],[2,0,1],'Kurang interaksi boleh merenggangkan hubungan. Rukun Negara menjadi panduan memperkukuh perpaduan.','Mulakan dengan keadaan tempat tinggal, kemudian kesan dan keperluannya.')],writtenPrompt='Terangkan tiga sebab pengenalan Rukun Negara. Nyatakan kesan setiap sebab terhadap hubungan masyarakat.',rubric=['Nyatakan perbezaan kegiatan ekonomi, pengasingan tempat tinggal dan perbezaan fahaman politik.','Terangkan bagaimana setiap sebab boleh mengurangkan interaksi atau merenggangkan hubungan.','Hubungkan penjelasan dengan keperluan memperkukuh perpaduan. Jangan menggantikan salah satu sebab dengan Peristiwa 13 Mei.']),dict(id='B',title='Matlamat dan prinsip',objective=c['learningObjectives'][1],questions=[q('akhir-matlamat','Padankan setiap situasi dengan matlamatnya.','match',['Penduduk berbilang kaum bekerjasama','Masyarakat menyertai perbincangan dan membuat pilihan','Kemakmuran dinikmati secara adil dan saksama','Tradisi kebudayaan pelbagai diterima dengan terbuka','Ilmu sains dan teknologi moden digunakan'],[2,4,0,3,1],'Lima matlamat merangkumi perpaduan, demokrasi, keadilan, sikap liberal terhadap tradisi kebudayaan dan masyarakat progresif.','Semak situasi satu demi satu. Perhatikan kata kerjasama, pilihan, saksama, tradisi dan teknologi.',['Masyarakat adil','Masyarakat progresif','Perpaduan lebih erat','Sikap liberal terhadap tradisi kebudayaan','Cara hidup demokratik']),q('akhir-prinsip','Padankan prinsip dengan maksudnya.','match',['Kepercayaan kepada Tuhan','Kesetiaan kepada Raja dan Negara','Keluhuran Perlembagaan','Kedaulatan Undang-undang','Kesopanan dan Kesusilaan'],[3,0,4,1,2],'Setiap prinsip mempunyai maksud tersendiri: pegangan agama, taat setia, undang-undang tertinggi, pematuhan undang-undang dan nilai murni.','Bezakan undang-undang tertinggi daripada pematuhan undang-undang. Lihat semula Misi 2.',['Taat setia kepada Raja dan negara','Menghormati dan mematuhi undang-undang','Mengamalkan nilai murni','Agama sebagai pegangan utama','Perlembagaan Persekutuan ialah undang-undang tertinggi negara'])],writtenPrompt='Pilih satu matlamat dan satu prinsip. Terangkan maksud kedua-duanya dan beri contoh bagi setiap satu.',rubric=['Nama matlamat dan prinsip mestilah tepat serta dibezakan.','Maksud perlu diterangkan dengan kata sendiri yang mengekalkan isi buku teks.','Contoh mesti menunjukkan hubungan dengan matlamat atau prinsip yang dipilih.']),dict(id='C',title='Peranan dalam kehidupan',objective=c['learningObjectives'][2],questions=[q('akhir-peranan','Padankan situasi dengan peranan yang paling langsung.','match',['Jiran bekerjasama membaiki taman','Murid menyiapkan hasil sendiri tanpa meniru','Aktiviti komuniti memberi ruang untuk keperluan ibadat'],[1,2,0],'Kerjasama mengukuhkan perpaduan; kejujuran membentuk jati diri; ruang ibadat meraikan kepelbagaian agama dan kepercayaan.','Kenal pasti tindakan utama dalam situasi, bukan sekadar menyebut bahawa tindakan itu baik.',['Meraikan kepelbagaian agama dan kepercayaan','Mengukuhkan perpaduan masyarakat','Membentuk jati diri']),q('akhir-patriotik','Murid membantu persediaan Hari Kebangsaan tanpa mengharapkan hadiah. Peranan apakah yang paling langsung?','choice',['Membentuk masyarakat patriotik','Memupuk sikap menghormati undang-undang','Meraikan kepelbagaian agama dan kepercayaan'],[0],'Sumbangan untuk sambutan kebangsaan menunjukkan cinta dan tanggungjawab terhadap negara, iaitu patriotisme.','Tumpukan kaitan tindakan dengan cinta akan negara, bukan aturan atau keperluan ibadat.')],writtenPrompt='Jelaskan sekurang-kurangnya tiga peranan Rukun Negara. Beri satu contoh tindakan dan kesannya bagi setiap peranan.',rubric=['Kenal pasti sekurang-kurangnya tiga peranan yang tepat daripada enam peranan buku teks.','Beri contoh tindakan yang relevan bagi setiap peranan, bukan mengulang frasa yang sama.','Jelaskan kesan tindakan terhadap diri atau masyarakat. Semakan guru menilai hubungan peranan, tindakan dan kesan.'])]
p.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
